def author(sid,plan):
    ep=ROOT/'studio/episodes'/sid;d=yaml.safe_load((ep/'script.yaml').read_text());assert len(plan)==len(d['sentences']),(sid,len(plan),len(d['sentences']))
    base=yaml.safe_load((ROOT/'studio/episodes/hb-c10-utkomststod/script.yaml').read_text());d['render']=copy.deepcopy(base['render']);d['render'].pop('background_identity',None);d['render']['background_image']=f'studio/media/{sid}/sources/background.jpg';d['render']['music_path']=f'studio/media/{sid}/sources/music-bed.flac';d['render']['credits']=d['render']['credits'][:2]
    sources=yaml.safe_load((ep/'sources.yaml').read_text());parts=['Svensk källtext med granskad rysk översättning.']
    for item in sources['sources']:parts +=[item['source'].get('title',item['attribution']['title']),item['attribution']['credit']]
    parts+=['Fullständiga källor och villkor i medföljande CREDITS.md.'];d['render']['credits'][0]['paragraphs']=list(dict.fromkeys(parts));d['render']['credits'][1]['paragraphs']=['Bild- och musikattribution fastställs i tillgångsregistret.','Lokal svensk berättarröst: Supertonic3 · F1.','Fullständiga källor och villkor i medföljande CREDITS.md.']
    d['episode_decisions']=[dict(id=k,decision=v,status='proposed',resolve_during=s) for k,v,s in [('fidelity','Exact body sentences and list fragments once, source order, current reviewed Russian; heading unspoken. No added medical/legal claims.','script'),('visuals','An individually planned relevant picture for each sentence; prioritize actual accurately identified licensed concrete objects,places,equipment and useful source-specific pictorial relationships. No invented diagnoses,medical procedures,numerical data or eligibility conditions.','script'),('voice','LocalSwedishSupertonic3F1,32steps,speed.95,NumPyseed42,44100HzmonoPCM16; pronunciation remains whole-video listening priority.','script'),('pace','3secondtitle,.25secondtextlead,measured fullspeech,1.5secondpause and2.2attopicends;2.5forlongpairs. Do not accelerate to targetlength.','script'),('background','A distinct licensed topic-related photograph with42%darken,2.5pxblur,15%relativezoom and continuous140secondglobalcyclicpan; exact source pending asset resolution, Chapter10oceanpalette.','assets'),('music','Distinct centrally reserved calm instrumental track with+2dBbedadjustment,duckingandfades; exact selected source pending asset resolution.','assets'),('closing','Actual source attribution derived from sources.yaml,15secondreadablecreditcards and fullmatching sidecar.','script')]]
    d['asset_requests']=[dict(id='episode_background',kind='background',description='Distinct verified licensed Finnish healthcare-topic photograph; exact identity resolved during assets.',fallback='Another source-verified distinct topical photograph; never reuse another episode background.'),dict(id='music_bed',kind='music',description='Distinct centrally reserved calm instrumental music; exact source/terms resolved during assets.',fallback='Another centrally reserved distinct calm instrumental master with verified reuse terms.'),dict(id='narration',kind='narration',description='One full exact local Swedish F1clip per sentence/listfragment.',fallback='Diagnostic-led bounded targeted retake preserving originaltakes and settings.')]
    scenes=[];last=None
    for i,(r,(title,kind,desc)) in enumerate(zip(d['sentences'],plan)):
        unit=r['sentence_id'].rsplit('-s',1)[0]
        if unit!=last:scenes.append(dict(id=f'scene-{len(scenes)+1}',description=title));last=unit
        key=f'picture-{i+1:03}';d['asset_requests'].append(dict(id=key,kind='foreground',description=kind+': '+desc,fallback='Accurate useful original pictorial explanation limited to this source statement; document honest omission if imagery would mislead.'))
        r.update(scene_id=scenes[-1]['id'],visual_cue=desc,asset_ids=['episode_background',key],pause_after_seconds=2.5 if len(r['sv'])>185 else 1.5,pronunciation_notes=['Swedish compounds, Finnish service names,abbreviations and numbers require whole-video listening; ASR is diagnostic only.'],render_caption=False)
        text=r['sv']
        for a,b in [('FPA:s','F P A:s'),('FPA','F P A'),('EES','E E S'),('EU','E U')]:text=text.replace(a,b)
        if text!=r['sv']:r['speech_override']=dict(text=text,reason='Distinct Swedish initial-letter speech for source abbreviations; display remains exact.',review_status='pending')
    d['scenes']=scenes
    for i in range(len(d['sentences'])):
        if i==len(d['sentences'])-1 or (d['sentences'][i+1]['scene_id']!=d['sentences'][i]['scene_id']):d['sentences'][i]['pause_after_seconds']=max(2.2,d['sentences'][i]['pause_after_seconds'])
    (ep/'script.yaml').write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False,width=100));(ep/'picture-plan.json').write_text(json.dumps([dict(sentence_id=r['sentence_id'],title=t,preferred_media=k,request=v) for r,(t,k,v) in zip(d['sentences'],plan)],ensure_ascii=False,indent=2)+'\n');print(sid,len(plan),'source-specific requests authored')
if __name__=='__main__':
    for sid,plan in PLANS.items():author(sid,plan)
